import java.util.ArrayList;
import java.util.List;

public class NaivePatternSearch implements PatternSearcher {

    private final String pattern;

    public NaivePatternSearch(String pattern) {
        if (pattern == null || pattern.isEmpty())
            throw new IllegalArgumentException("Pattern must be non-empty");
        this.pattern = pattern;
    }

    @Override
    public List<Integer> search(String text) {
        if (text == null)
            throw new IllegalArgumentException("Text must not be null");

        List<Integer> matches = new ArrayList<>();
        int patternLen = pattern.length();
        int textLen = text.length();

        for (int i = 0; i <= textLen - patternLen; i++) {
            if (matchesAt(text, i))
                matches.add(i);
        }

        return matches;
    }

    private boolean matchesAt(String text, int startIndex) {
        for (int i = 0; i < pattern.length(); i++) {
            if (text.charAt(startIndex + i) != pattern.charAt(i))
                return false;
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;

public class NaivePatternSearch implements PatternSearcher {

    private final String pattern;

    public NaivePatternSearch(String pattern) {
        if (pattern == null || pattern.isEmpty())
            throw new InvalidPatternException(pattern);
        this.pattern = pattern;
    }

    @Override
    public List<Integer> search(String text) {
        if (text == null)
            throw new IllegalArgumentException("Text must not be null");

        List<Integer> matches = new ArrayList<>();
        int patternLen = pattern.length();
        int textLen = text.length();

        for (int i = 0; i <= textLen - patternLen; i++) {
            if (matchesAt(text, i))
                matches.add(i);
        }

        return matches;
    }

    private boolean matchesAt(String text, int startIndex) {
        for (int i = 0; i < pattern.length(); i++) {
            if (text.charAt(startIndex + i) != pattern.charAt(i))
                return false;
        }
        return true;
    }
}

public class PatternSearchFactory {

    public enum Algorithm {
        NAIVE
    }

    public static PatternSearcher create(String pattern, Algorithm algorithm) {
        switch (algorithm) {
            case NAIVE: return new NaivePatternSearch(pattern);
            default: throw new IllegalArgumentException("Unknown algorithm: " + algorithm);
        }
    }

    public static PatternSearcher create(String pattern) {
        return create(pattern, Algorithm.NAIVE);
    }
}
